<section class="admin-head"><div><p class="kicker">Commerce Core</p><h1>Orders</h1><p>Immutable order snapshots, payment state and fulfilment workflow.</p></div></section>
<div class="admin-filter-row"><a class="status-pill" href="<?=e(url('/admin/orders'))?>">All</a><?php foreach(['PENDING_PAYMENT','PAID','CONFIRMED','IN_PRODUCTION','READY_TO_DISPATCH','SHIPPED','DELIVERED','CANCELLED','REFUND_PENDING','REFUNDED'] as $s):?><a class="status-pill commerce <?=e(strtolower($s))?>" href="<?=e(url('/admin/orders?status='.$s))?>"><?=e(str_replace('_',' ',$s))?></a><?php endforeach;?></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Payment</th><th>Total</th><th>Placed</th><th></th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="7">No orders match this filter.</td></tr><?php endif;?><?php foreach($orders as $o):?><tr><td><strong><?=e($o['number'])?></strong><br><small><?=count($o['items'])?> item(s)</small></td><td><?=e($o['customer_snapshot']['name']??'')?><br><small><?=e($o['address_snapshot']['city']??'')?> · <?=e($o['address_snapshot']['pincode']??'')?></small></td><td><span class="status-pill commerce <?=e(strtolower($o['status']))?>"><?=e(str_replace('_',' ',$o['status']))?></span></td><td><?=e($o['payment_status'])?></td><td><?=money($o['pricing']['grand_total'])?></td><td><?=e(date('d M Y H:i',strtotime($o['created_at'])))?></td><td><a href="<?=e(url('/admin/order/'.$o['guid']))?>">Open →</a></td></tr><?php endforeach;?></tbody></table></div>
